:root {
  --warna-utama: #3b4cca;
  --warna-latar: #f5f6fb;
  --warna-kartu: #ffffff;
  --warna-teks: #1b1d29;
  --warna-redup: #5c6070;
  --benar: #1f7a3d;
  --benar-latar: #e3f4e8;
  --salah: #b3261e;
  --salah-latar: #fbe7e5;
  --sudut: 0.75rem;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.5;
  color: var(--warna-teks);
  background: var(--warna-latar);
}

.wadah { max-width: 36rem; margin: 0 auto; padding: 2rem 1rem; }

h1 { margin: 0 0 1.5rem; font-size: 1.75rem; }
h2 { margin: 0; font-size: 1.25rem; line-height: 1.35; }
h3 { margin: 2rem 0 0.75rem; font-size: 1.1rem; }

.redup { color: var(--warna-redup); }

button, input { font: inherit; }

button {
  cursor: pointer;
  border: 0;
  border-radius: var(--sudut);
  padding: 0.75rem 1.25rem;
}
button:disabled { cursor: not-allowed; opacity: 0.6; }
.utama { background: var(--warna-utama); color: #fff; font-weight: 600; width: 100%; margin-top: 1rem; }

:focus-visible { outline: 3px solid var(--warna-utama); outline-offset: 2px; }
h2:focus { outline: none; } /* judul hanya menerima fokus dari JavaScript */

.opsi-waktu { display: flex; gap: 0.5rem; align-items: center; margin: 1rem 0; }

.status-kuis { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 0 1rem; font-weight: 600; }
.status-kuis p { margin: 0; }
.waktu { color: var(--salah); }

progress {
  width: 100%;
  height: 0.75rem;
  margin: 0.5rem 0 1.5rem;
  accent-color: var(--warna-utama);
}

fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
legend { padding: 0; margin-bottom: 1rem; }

.pilihan { display: grid; gap: 0.5rem; }
.pilihan label {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  padding: 0.75rem 1rem;
  background: var(--warna-kartu);
  border: 2px solid #d5d8e3;
  border-radius: var(--sudut);
  cursor: pointer;
  overflow-wrap: anywhere;
}
.pilihan input { width: 1.25rem; height: 1.25rem; flex: none; accent-color: var(--warna-utama); }
.pilihan label:has(input:checked:enabled) { border-color: var(--warna-utama); } /* :enabled: setelah dinilai, warna benar/salah yang menang */
.pilihan label:has(input:focus-visible) { outline: 3px solid var(--warna-utama); outline-offset: 2px; }
.pilihan input:focus-visible { outline: none; }

/* Benar/salah: warna + garis tebal + teks, tidak hanya warna */
.pilihan label.benar { border-color: var(--benar); background: var(--benar-latar); border-width: 3px; }
.pilihan label.salah { border-color: var(--salah); background: var(--salah-latar); border-style: dashed; border-width: 3px; }
.penanda { margin-left: auto; font-size: 0.875rem; font-weight: 700; white-space: nowrap; }
.benar .penanda { color: var(--benar); }
.salah .penanda { color: var(--salah); }

.umpan-balik:not(:empty) { margin-top: 1rem; padding: 1rem; border-radius: var(--sudut); border-left: 6px solid; }
.umpan-balik.benar { background: var(--benar-latar); border-color: var(--benar); }
.umpan-balik.salah { background: var(--salah-latar); border-color: var(--salah); }
.umpan-balik p { margin: 0; }
.umpan-balik p + p { margin-top: 0.5rem; }

.ringkasan { font-size: 1.5rem; font-weight: 700; margin: 0.5rem 0; }
.tinjauan { padding-left: 1.25rem; }
.tinjauan li { margin-bottom: 1rem; }
.tinjauan p { margin: 0.25rem 0; }

@media (prefers-reduced-motion: no-preference) {
  .pilihan label { transition: border-color 0.15s, background-color 0.15s; }
}

const $ = (sel) => document.querySelector(sel);
const layar = { mulai: $("#layar-mulai"), soal: $("#layar-soal"), hasil: $("#layar-hasil") };
const form = $("#form-soal");
const tombolMulai = $("#tombol-mulai");

let bankSoal = [];   // semua soal dari soal.json
let soal = [];       // urutan soal untuk satu permainan
let nomor = 0;       // indeks soal yang sedang tampil

// Fisher-Yates: tiap urutan punya peluang yang sama. Mengembalikan salinan baru.
function acak(daftar) {
  const a = [...daftar];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function soalValid(s) {
  return typeof s.pertanyaan === "string" &&
    Array.isArray(s.pilihan) && s.pilihan.length >= 2 &&
    Number.isInteger(s.jawaban) && s.jawaban >= 0 && s.jawaban < s.pilihan.length;
}

async function muatSoal() {
  try {
    const res = await fetch("soal.json"); // jalur relatif: tetap jalan di github.io/nama-repo/
    if (!res.ok) throw new Error("HTTP " + res.status);
    const data = await res.json();
    bankSoal = data.filter(soalValid);
    if (bankSoal.length === 0) throw new Error("Tidak ada soal yang valid");
    $("#info-kuis").textContent = `Ada ${bankSoal.length} soal pilihan ganda. Pilih jawaban dengan mouse atau tombol panah, lalu tekan Enter.`;
    tombolMulai.disabled = false;
  } catch (err) {
    console.error(err);
    $("#info-kuis").textContent = "Soal gagal dimuat. Buka halaman ini lewat server (http://, bukan file://) dan pastikan soal.json valid.";
  }
}

function tampilkanLayar(nama, judul) {
  for (const [kunci, el] of Object.entries(layar)) el.hidden = kunci !== nama;
  $(judul).focus(); // pindahkan fokus supaya pembaca layar mulai dari judul layar baru
}

function mulai() {
  soal = acak(bankSoal).map((s) => ({
    ...s,
    // simpan teks jawaban benar, karena urutan pilihan ikut diacak
    pilihanAcak: acak(s.pilihan.map((teks, i) => ({ teks, benar: i === s.jawaban }))),
  }));
  nomor = 0;
  $("#kemajuan").max = soal.length;
  tampilkanSoal();
}

function tampilkanSoal() {
  const s = soal[nomor];
  $("#posisi").textContent = `Soal ${nomor + 1} dari ${soal.length}`;
  $("#kemajuan").value = nomor;
  $("#judul-soal").textContent = s.pertanyaan;

  const opsi = s.pilihanAcak.map((p, i) => {
    const label = document.createElement("label");
    const radio = document.createElement("input");
    radio.type = "radio";
    radio.name = "jawaban"; // name yang sama = satu grup radio
    radio.value = i;
    radio.required = true;
    const teks = document.createElement("span");
    teks.textContent = p.teks; // textContent: "<h1>" tampil sebagai teks
    label.append(radio, teks);
    return label;
  });
  $("#pilihan").replaceChildren(...opsi);

  tampilkanLayar("soal", "#judul-soal");
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const dipilih = form.elements.jawaban.value; // "" kalau belum memilih
  if (dipilih === "") return;
  // Sementara: lihat di Console. Langkah berikutnya memeriksa jawabannya.
  console.log("Kamu memilih:", soal[nomor].pilihanAcak[dipilih]);
});

tombolMulai.addEventListener("click", mulai);
muatSoal();

