  const s = soal[nomor];
  sudahDijawab = false;
  $("#posisi").textContent = `Soal ${nomor + 1} dari ${soal.length}`;
  $("#skor").textContent = `Skor: ${skor}`;
  $("#kemajuan").value = nomor;
  $("#judul-soal").textContent = s.pertanyaan;

  const opsi = s.pilihanAcak.map((p, i) => {
    const label = document.createElement("label");
    const radio = document.createElement("input");
    radio.type = "radio";
    radio.name = "jawaban"; // name yang sama = satu grup radio
    radio.value = i;
    radio.required = true;
    const teks = document.createElement("span");
    teks.textContent = p.teks; // textContent: "<h1>" tampil sebagai teks
    label.append(radio, teks);
    return label;
  });
  $("#pilihan").replaceChildren(...opsi);

  umpanBalik.replaceChildren();
  umpanBalik.className = "umpan-balik";
  tombolPeriksa.hidden = false;
  tombolLanjut.hidden = true;
  tampilkanLayar("soal", "#judul-soal");
}

function tandai(label, kelas, teks) {
  label.classList.add(kelas);
  const penanda = document.createElement("span");
  penanda.className = "penanda";
  penanda.textContent = teks;
  label.append(penanda);
}

function periksa(pilihanIndeks) {
  if (sudahDijawab) return;
  sudahDijawab = true;

  const s = soal[nomor];
  const benar = s.pilihanAcak.find((p) => p.benar);
  const tepat = s.pilihanAcak[pilihanIndeks].benar;
  if (tepat) skor++;

  const label = [...$("#pilihan").children];
  label.forEach((l, i) => {
    l.querySelector("input").disabled = true;
    if (s.pilihanAcak[i].benar) tandai(l, "benar", "✓ Jawaban benar");
    else if (i === pilihanIndeks) tandai(l, "salah", "✗ Jawabanmu");
  });

  const judul = document.createElement("p");
  const strong = document.createElement("strong");
  if (tepat) strong.textContent = "✓ Benar!";
  else strong.textContent = `✗ Kurang tepat. Jawaban yang benar: ${benar.teks}`;
  judul.append(strong);
  const penjelasan = document.createElement("p");
  penjelasan.textContent = s.penjelasan ?? "";
  umpanBalik.className = "umpan-balik " + (tepat ? "benar" : "salah");
  umpanBalik.replaceChildren(judul, penjelasan);

  $("#skor").textContent = `Skor: ${skor}`;
  $("#kemajuan").value = nomor + 1;
  tombolPeriksa.hidden = true;
  tombolLanjut.hidden = false;
  tombolLanjut.textContent = nomor + 1 < soal.length ? "Soal berikutnya" : "Lihat hasil";
  tombolLanjut.focus(); // fokus tidak hilang saat tombol Periksa disembunyikan
}

// Versi sementara: hanya skor. Langkah berikutnya menambah rekor dan tinjauan.
function tampilkanHasil() {
  const persen = Math.round((skor / soal.length) * 100);
  $("#ringkasan").textContent = `Skor ${skor} dari ${soal.length} (${persen}%)`;
  tampilkanLayar("hasil", "#judul-hasil");
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const dipilih = form.elements.jawaban.value; // "" kalau belum memilih
  if (dipilih === "") return;
  periksa(Number(dipilih));
});

tombolLanjut.addEventListener("click", () => {
  nomor++;
  if (nomor < soal.length) tampilkanSoal();
  else tampilkanHasil();
});

tombolMulai.addEventListener("click", mulai);
$("#tombol-ulang").addEventListener("click", () => tampilkanLayar("mulai", "#judul-mulai"));

muatSoal();

const KUNCI_REKOR = "kuis-skor-tertinggi";
const DETIK_PER_SOAL = 20;

const $ = (sel) => document.querySelector(sel);
const layar = { mulai: $("#layar-mulai"), soal: $("#layar-soal"), hasil: $("#layar-hasil") };
const form = $("#form-soal");
const tombolMulai = $("#tombol-mulai");
const tombolPeriksa = $("#tombol-periksa");
const tombolLanjut = $("#tombol-lanjut");
const umpanBalik = $("#umpan-balik");
const kotakWaktu = $("#waktu");

let bankSoal = [];   // semua soal dari soal.json
let soal = [];       // urutan soal untuk satu permainan
let nomor = 0;       // indeks soal yang sedang tampil
let skor = 0;
let salah = [];      // catatan untuk layar hasil
let sudahDijawab = false;
let sisaDetik = 0;
let pengatur = null; // id dari setInterval

// Fisher-Yates: tiap urutan punya peluang yang sama. Mengembalikan salinan baru.
function acak(daftar) {
  const a = [...daftar];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function soalValid(s) {
  return typeof s.pertanyaan === "string" &&
    Array.isArray(s.pilihan) && s.pilihan.length >= 2 &&
    Number.isInteger(s.jawaban) && s.jawaban >= 0 && s.jawaban < s.pilihan.length;
}

async function muatSoal() {
  try {
    const res = await fetch("soal.json"); // jalur relatif: tetap jalan di github.io/nama-repo/
    if (!res.ok) throw new Error("HTTP " + res.status);
    const data = await res.json();
    bankSoal = data.filter(soalValid);
    if (bankSoal.length === 0) throw new Error("Tidak ada soal yang valid");
    $("#info-kuis").textContent = `Ada ${bankSoal.length} soal pilihan ganda. Pilih jawaban dengan mouse atau tombol panah, lalu tekan Enter.`;
    tombolMulai.disabled = false;
  } catch (err) {
    console.error(err);
    $("#info-kuis").textContent = "Soal gagal dimuat. Buka halaman ini lewat server (http://, bukan file://) dan pastikan soal.json valid.";
  }
}

function bacaRekor() {
  try {
    return Number(localStorage.getItem(KUNCI_REKOR)) || 0;
  } catch {
    return 0; // localStorage diblokir: anggap belum ada rekor
  }
}

function simpanRekor(nilai) {
  try {
    localStorage.setItem(KUNCI_REKOR, String(nilai));
  } catch {
    // tidak bisa menyimpan: kuis tetap jalan
  }
}

function tampilkanLayar(nama, judul) {
  for (const [kunci, el] of Object.entries(layar)) el.hidden = kunci !== nama;
  $(judul).focus(); // pindahkan fokus supaya pembaca layar mulai dari judul layar baru
}

function tampilkanRekor() {
  const rekor = bacaRekor();
  $("#skor-tertinggi").textContent = rekor ? `Skor tertinggimu: ${rekor}%` : "";
}

function mulai() {
  soal = acak(bankSoal).map((s) => ({
    ...s,
    // simpan teks jawaban benar, karena urutan pilihan ikut diacak
    pilihanAcak: acak(s.pilihan.map((teks, i) => ({ teks, benar: i === s.jawaban }))),
  }));
  nomor = 0;
  skor = 0;
  salah = [];
  $("#kemajuan").max = soal.length;
  tampilkanSoal();
}

function tampilkanSoal() {
  const s = soal[nomor];
  sudahDijawab = false;
  $("#posisi").textContent = `Soal ${nomor + 1} dari ${soal.length}`;
  $("#skor").textContent = `Skor: ${skor}`;
  $("#kemajuan").value = nomor;
  $("#judul-soal").textContent = s.pertanyaan;

  const opsi = s.pilihanAcak.map((p, i) => {
    const label = document.createElement("label");
    const radio = document.createElement("input");
    radio.type = "radio";
    radio.name = "jawaban"; // name yang sama = satu grup radio
    radio.value = i;
    radio.required = true;
    const teks = document.createElement("span");
    teks.textContent = p.teks; // textContent: "<h1>" tampil sebagai teks
    label.append(radio, teks);
    return label;
  });
  $("#pilihan").replaceChildren(...opsi);

  umpanBalik.replaceChildren();
  umpanBalik.className = "umpan-balik";
  tombolPeriksa.hidden = false;
  tombolLanjut.hidden = true;
  tampilkanLayar("soal", "#judul-soal");
  mulaiWaktu();
}

function mulaiWaktu() {
  clearInterval(pengatur);
  kotakWaktu.hidden = !$("#pakai-waktu").checked;
  if (kotakWaktu.hidden) return;
  sisaDetik = DETIK_PER_SOAL;
  kotakWaktu.textContent = `Sisa waktu: ${sisaDetik} detik`;
  pengatur = setInterval(() => {
    sisaDetik--;
    kotakWaktu.textContent = `Sisa waktu: ${sisaDetik} detik`;
    if (sisaDetik <= 0) periksa(null);
  }, 1000);
}

function tandai(label, kelas, teks) {
  label.classList.add(kelas);
  const penanda = document.createElement("span");
  penanda.className = "penanda";
  penanda.textContent = teks;
  label.append(penanda);
}

// pilihanIndeks = null berarti waktu habis
function periksa(pilihanIndeks) {
  if (sudahDijawab) return;
  sudahDijawab = true;
  clearInterval(pengatur);

  const s = soal[nomor];
  const benar = s.pilihanAcak.find((p) => p.benar);
  const dipilih = pilihanIndeks === null ? null : s.pilihanAcak[pilihanIndeks];
  const tepat = dipilih?.benar === true;
  if (tepat) skor++;
  else salah.push({ pertanyaan: s.pertanyaan, jawabanmu: dipilih?.teks ?? null, jawabanBenar: benar.teks, penjelasan: s.penjelasan });

  const label = [...$("#pilihan").children];
  label.forEach((l, i) => {
    l.querySelector("input").disabled = true;
    if (s.pilihanAcak[i].benar) tandai(l, "benar", "✓ Jawaban benar");
    else if (i === pilihanIndeks) tandai(l, "salah", "✗ Jawabanmu");
  });

  const judul = document.createElement("p");
  const strong = document.createElement("strong");
  if (tepat) strong.textContent = "✓ Benar!";
  else if (dipilih) strong.textContent = `✗ Kurang tepat. Jawaban yang benar: ${benar.teks}`;
  else strong.textContent = `⏱ Waktu habis. Jawaban yang benar: ${benar.teks}`;
  judul.append(strong);
  const penjelasan = document.createElement("p");
  penjelasan.textContent = s.penjelasan ?? "";
  umpanBalik.className = "umpan-balik " + (tepat ? "benar" : "salah");
  umpanBalik.replaceChildren(judul, penjelasan);

  $("#skor").textContent = `Skor: ${skor}`;
  $("#kemajuan").value = nomor + 1;
  tombolPeriksa.hidden = true;
  tombolLanjut.hidden = false;
  tombolLanjut.textContent = nomor + 1 < soal.length ? "Soal berikutnya" : "Lihat hasil";
  tombolLanjut.focus(); // fokus tidak hilang saat tombol Periksa disembunyikan
}

function tampilkanHasil() {
  const persen = Math.round((skor / soal.length) * 100);
  const rekorLama = bacaRekor();
  $("#ringkasan").textContent = `Skor ${skor} dari ${soal.length} (${persen}%)`;
  if (persen > rekorLama) {
    simpanRekor(persen);
    $("#rekor").textContent = "Rekor baru! Skor tertinggimu sekarang " + persen + "%.";
  } else {
    $("#rekor").textContent = `Skor tertinggimu: ${rekorLama}%.`;
  }

  const item = salah.map((x) => {
    const li = document.createElement("li");
    const q = document.createElement("p");
    const b = document.createElement("strong");
    b.textContent = x.pertanyaan;
    q.append(b);
    const kamu = document.createElement("p");
    kamu.textContent = "Jawabanmu: " + (x.jawabanmu ?? "tidak dijawab (waktu habis)");
    const kunci = document.createElement("p");
    kunci.textContent = "Jawaban benar: " + x.jawabanBenar;
    const alasan = document.createElement("p");
    alasan.className = "redup";
    alasan.textContent = x.penjelasan ?? "";
    li.append(q, kamu, kunci, alasan);
    return li;
  });
  if (item.length === 0) {
    const li = document.createElement("li");
    li.textContent = "Tidak ada. Semua jawabanmu benar!";
    item.push(li);
  }
  $("#tinjauan").replaceChildren(...item);
  tampilkanLayar("hasil", "#judul-hasil");
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const dipilih = form.elements.jawaban.value; // "" kalau belum memilih
  if (dipilih === "") return;
  periksa(Number(dipilih));
});

tombolLanjut.addEventListener("click", () => {
  nomor++;
  if (nomor < soal.length) tampilkanSoal();
  else tampilkanHasil();
});

tombolMulai.addEventListener("click", mulai);
$("#tombol-ulang").addEventListener("click", () => {
  tampilkanRekor();
  tampilkanLayar("mulai", "#judul-mulai");
});

